"""Compare two DNA sequences using DotPlot method.

    **Keyword arguments:**
    seqA -- first sequence
    seqB -- second sequence
  """
def dotPlot(seqA: str, seqB: str) -> list {
    la = len(seqA);
    lb = len(seqB);
    M = [[' ' for n in range(la)] for m in range(lb)];
    for i in range(lb) {
        for j in range(la) {
            if (seqB[i] == seqA[j]) {
                M[i][j] = 'x';
            }
        }
    }
    return M;
}

