    Attributes
    ----------
    header : dictionary
        a dictionary of HTTP headers

    Returns
    ----------
    cookie :
        Set-Cookie header as a dictionary
    """
def getKeys(header: Any) -> object {
    cookie = {};
    keySections = header['Set-Cookie'].split(", ");
    for x in keySections {
        cookie[x.split('=')[0]] = x.split('=')[1];
    }
    return cookie;
}

